operations.schema:
input SetPortfolioDetailsInput {
  name: String
  baseCurrency: String
  autoSnapshotEnabled: Boolean
  autoSnapshotIntervalHours: Int
}

operations.reducer:
if (action.input.baseCurrency != null && !/^[A-Z]{3}$/.test(action.input.baseCurrency)) {
  throw new InvalidCurrencyError(`${action.input.baseCurrency} is not a 3-letter currency code`);
}
if (
  action.input.baseCurrency != null &&
  action.input.baseCurrency !== state.baseCurrency &&
  state.snapshots.length > 0
) {
  throw new CurrencyLockedError("Cannot change the base currency once snapshots exist");
}
if (action.input.name != null) state.name = action.input.name;
if (action.input.baseCurrency != null) state.baseCurrency = action.input.baseCurrency;
if (action.input.autoSnapshotEnabled != null) state.autoSnapshot.enabled = action.input.autoSnapshotEnabled;
if (action.input.autoSnapshotIntervalHours != null) state.autoSnapshot.intervalHours = action.input.autoSnapshotIntervalHours;

const address = action.input.address.toLowerCase();
if (state.addresses.some((a) => a.address === address && a.chainId === action.input.chainId)) {
  throw new AddressKnownError(`${address} on chain ${action.input.chainId} is already tracked`);
}
state.addresses.push({
  id: action.input.id,
  address,
  chainId: action.input.chainId,
  label: action.input.label ?? null,
  ensName: action.input.ensName ?? null,
  tags: [],
  ignored: false,
  addedAt: action.input.timestamp,
});

operations.schema:
input UpdateAddressInput {
  id: OID!
  label: String
  ensName: String
  tags: [String!]
}

operations.reducer:
const entry = state.addresses.find((a) => a.id === action.input.id);
if (!entry) throw new AddressNotFoundError(`Address ${action.input.id} is not tracked`);
if (action.input.label != null) entry.label = action.input.label;
if (action.input.ensName != null) entry.ensName = action.input.ensName;
if (action.input.tags != null) entry.tags = action.input.tags;

operations.schema:
input RemoveAddressInput {
  id: OID!
}

operations.reducer:
const index = state.addresses.findIndex((a) => a.id === action.input.id);
if (index === -1) throw new AddressNotFoundError(`Address ${action.input.id} is not tracked`);
state.addresses.splice(index, 1);

operations.schema:
input SetAddressIgnoredInput {
  id: OID!
  ignored: Boolean!
}

operations.reducer:
const entry = state.addresses.find((a) => a.id === action.input.id);
if (!entry) throw new AddressNotFoundError(`Address ${action.input.id} is not tracked`);
entry.ignored = action.input.ignored;

operations.schema:
input SetPriceOverrideInput {
  asset: String!
  price: String!
  setAt: DateTime!
}

operations.reducer:
if (!/^(0|[1-9][0-9]*)(\.[0-9]+)?$/.test(action.input.price)) {
  throw new InvalidAmountError(`${action.input.price} is not a decimal amount`);
}
const existing = state.priceOverrides.find((p) => p.asset === action.input.asset);
if (existing) {
  existing.price = action.input.price;
  existing.setAt = action.input.setAt;
} else {
  state.priceOverrides.push({ asset: action.input.asset, price: action.input.price, setAt: action.input.setAt });
}

operations.schema:
input RemovePriceOverrideInput {
  asset: String!
}

input SetAssetIgnoredInput {
  asset: String!
  ignored: Boolean!
}

operations.reducer:
if (action.input.ignored) {
  if (!state.ignoredAssets.includes(action.input.asset)) {
    state.ignoredAssets.push(action.input.asset);
  }
} else {
  state.ignoredAssets = state.ignoredAssets.filter((a) => a !== action.input.asset);
}

operations.schema:
input TakeSnapshotInput {
  id: OID!
  timestamp: DateTime!
  totalValue: String!
  netWorth: String
  liabilities: [SnapshotLiabilityInput!]
  perLocation: [LocationValueInput!]!
  perAsset: [AssetValueInput!]!
}

input SnapshotLiabilityInput {
  asset: String!
  amount: String!
}

input LocationValueInput {
  location: String!
  value: String!
}

input AssetValueInput {
  asset: String!
  amount: String!
  value: String!
}

operations.reducer:
const isDecimal = (value) =>
  /^(0|[1-9][0-9]*)(\.[0-9]+)?$/.test(value);
// Ledger-derived holdings can net negative when a wallet's history
// cannot account every inflow (internal transfers are invisible
// without traces); the snapshot records that honestly instead of
// losing the asset.
const isSignedDecimal = (value) =>
  /^-?(0|[1-9][0-9]*)(\.[0-9]+)?$/.test(value);
if (
  action.input.perLocation.length === 0 &&
  action.input.perAsset.length === 0
) {
  throw new SnapshotEmptyError(
    "A snapshot needs at least one location or asset value",
  );
}
const signedAmounts = [
  action.input.totalValue,
  ...action.input.perLocation.map((l) => l.value),
  ...action.input.perAsset.flatMap((a) => [a.amount, a.value]),
];
for (const amount of signedAmounts) {
  if (!isSignedDecimal(amount))
    throw new InvalidAmountError(`${amount} is not a decimal amount`);
}
for (const liability of action.input.liabilities ?? []) {
  if (!isDecimal(liability.amount))
    throw new InvalidAmountError(
      `${liability.amount} is not a decimal amount`,
    );
}
if (
  action.input.netWorth != null &&
  !/^-?(0|[1-9][0-9]*)(\.[0-9]+)?$/.test(action.input.netWorth)
) {
  throw new InvalidAmountError(
    `${action.input.netWorth} is not a decimal amount`,
  );
}
// The id is the snapshot's identity: a re-run of a timed step re-takes
// the same timestamp, and that replaces the stored snapshot instead of
// appending a second row with one id - the read model upserts by id and
// two rows for one id break the insert.
const snapshot = {
  id: action.input.id,
  timestamp: action.input.timestamp,
  totalValue: action.input.totalValue,
  netWorth: action.input.netWorth ?? null,
  liabilities: action.input.liabilities ?? [],
  perLocation: action.input.perLocation,
  perAsset: action.input.perAsset,
};
const at = state.snapshots.findIndex((s) => s.id === action.input.id);
if (at === -1) state.snapshots.push(snapshot);
else state.snapshots[at] = snapshot;

operations.schema:
input DeleteSnapshotInput {
  id: OID!
}

operations.reducer:
const index = state.snapshots.findIndex((s) => s.id === action.input.id);
if (index === -1) throw new SnapshotNotFoundError(`Snapshot ${action.input.id} does not exist`);
state.snapshots.splice(index, 1);

operations.schema:
input RecordResourcesInput {
  connectionId: String!
  workflowIds: [String!]!
}

operations.reducer:
state.resources = {
  connectionId: action.input.connectionId,
  workflowIds: action.input.workflowIds,
};

operations.schema:
input RecordCheckInput {
  at: DateTime!
  issues: [IssueInput!]!
  fixes: [FixInput!]!
}

input IssueInput {
  code: String!
  severity: IssueSeverity!
  message: String!
  accountId: String
}

input FixInput {
  code: String!
  message: String!
  at: DateTime!
}

operations.reducer:
state.lastCheck = {
  at: action.input.at,
  issues: action.input.issues.map((i) => ({
    code: i.code,
    severity: i.severity,
    message: i.message,
    accountId: i.accountId ?? null,
  })),
  fixes: action.input.fixes,
};

operations.schema:
input SetGrantInput {
  id: String!
  name: String
  grantedAt: DateTime
}

operations.reducer:
state.grant = {
  id: action.input.id,
  name: action.input.name ?? null,
  grantedAt: action.input.grantedAt ?? null,
};

operations.schema:
input ClearGrantInput {
  _empty: Boolean
}

input SetPositionsInput {
  wallet: String!
  chainId: Int!
  fetchedAt: DateTime!
  positions: [PositionInput!]!
}

input PositionInput {
  protocol: String!
  kind: PositionKind!
  assets: [PositionAssetInput!]!
  note: String
}

input PositionAssetInput {
  asset: String!
  amount: String!
}

operations.reducer:
const entry = {
  wallet: action.input.wallet,
  chainId: action.input.chainId,
  fetchedAt: action.input.fetchedAt,
  positions: action.input.positions,
};
// Documents created before the positions field existed carry no key at
// all; without this backfill SET_POSITIONS throws and the sweep fails.
if (!Array.isArray(state.positions)) {
  state.positions = [];
}
const index = state.positions.findIndex(
  (p) => p.wallet === action.input.wallet && p.chainId === action.input.chainId,
);
if (index === -1) {
  state.positions.push(entry);
} else {
  state.positions[index] = entry;
};

operations.schema:
input AddBundleInput {
  id: OID!
  name: String!
  addresses: [String!]!
}

operations.reducer:
if (!state.bundles) state.bundles = [];
const name = action.input.name.trim();
if (!name) throw new EmptyBundleError("A bundle needs a name");
if (state.bundles.some((b) => b.name.toLowerCase() === name.toLowerCase())) {
  throw new DuplicateBundleNameError(`A bundle named ${name} exists`);
}
const addresses = [...new Set(action.input.addresses.map((a) => a.toLowerCase()))];
if (addresses.length === 0) throw new EmptyBundleError("A bundle needs at least one wallet");
const known = new Set(state.addresses.map((a) => a.address));
const unknown = addresses.find((a) => !known.has(a));
if (unknown) throw new UnknownBundleAddressError(`${unknown} is not in the portfolio`);
state.bundles.push({ id: action.input.id, name, addresses });

operations.schema:
input UpdateBundleInput {
  id: OID!
  name: String
  addresses: [String!]
}

operations.reducer:
if (!state.bundles) state.bundles = [];
const bundle = state.bundles.find((b) => b.id === action.input.id);
if (!bundle) throw new BundleNotFoundError(`Bundle ${action.input.id} does not exist`);
if (action.input.name != null) {
  const name = action.input.name.trim();
  if (!name) throw new EmptyBundleError("A bundle needs a name");
  if (state.bundles.some((b) => b.id !== bundle.id && b.name.toLowerCase() === name.toLowerCase())) {
    throw new DuplicateBundleNameError(`A bundle named ${name} exists`);
  }
  bundle.name = name;
}
if (action.input.addresses != null) {
  const addresses = [...new Set(action.input.addresses.map((a) => a.toLowerCase()))];
  if (addresses.length === 0) throw new EmptyBundleError("A bundle needs at least one wallet");
  const known = new Set(state.addresses.map((a) => a.address));
  const unknown = addresses.find((a) => !known.has(a));
  if (unknown) throw new UnknownBundleAddressError(`${unknown} is not in the portfolio`);
  bundle.addresses = addresses;
}

operations.schema:
input RemoveBundleInput {
  id: OID!
}

operations.reducer:
if (!state.bundles) state.bundles = [];
const index = state.bundles.findIndex((b) => b.id === action.input.id);
if (index === -1) throw new BundleNotFoundError(`Bundle ${action.input.id} does not exist`);
state.bundles.splice(index, 1);

const counterparty = action.input.counterparty.trim().toLowerCase();
if (!/^0x[0-9a-f]{40}$/.test(counterparty)) {
  throw new InvalidCounterpartyError(`${action.input.counterparty} is not an address`);
}
if (!state.categoryRules) state.categoryRules = [];
state.categoryRules.push({
  id: action.input.id,
  counterparty,
  chainId: action.input.chainId ?? null,
  direction: action.input.direction,
  asset: action.input.asset ?? null,
  category: action.input.category,
  label: action.input.label?.trim() || null,
});

operations.schema:
input UpdateCategoryRuleInput {
  id: OID!
  category: TxCategory
  direction: CategoryDirection
  label: String
}

operations.reducer:
const rule = (state.categoryRules ?? []).find((r) => r.id === action.input.id);
if (!rule) throw new CategoryRuleNotFoundError(`Rule ${action.input.id} does not exist`);
if (action.input.category != null) rule.category = action.input.category;
if (action.input.direction != null) rule.direction = action.input.direction;
if (action.input.label != null) rule.label = action.input.label.trim() || null;

operations.schema:
input RemoveCategoryRuleInput {
  id: OID!
}

operations.reducer:
const rules = state.categoryRules ?? [];
const index = rules.findIndex((r) => r.id === action.input.id);
if (index === -1) throw new CategoryRuleNotFoundError(`Rule ${action.input.id} does not exist`);
rules.splice(index, 1);

operations.schema:
input SetEventCategoriesInput {
  overrides: [CategoryOverrideInput!]!
}

input CategoryOverrideInput {
  wallet: String!
  eventId: String!
  sequenceIndex: Int!
  category: TxCategory!
  giftCost: String
  giftAcquiredAt: DateTime
}

operations.reducer:
if (!state.categoryOverrides) state.categoryOverrides = [];
const overrides = state.categoryOverrides;
const keyOf = (o: { wallet: string; eventId: string; sequenceIndex: number }) => `${o.wallet.toLowerCase()}|${o.eventId}|${o.sequenceIndex}`;
for (const o of action.input.overrides) {
  if ((o.giftCost != null || o.giftAcquiredAt != null) && o.category !== "GIFT_IN") {
    throw new InvalidGiftBasisError("Gift cost and date belong on a GIFT_IN override only");
  }
  if (o.giftCost != null && !/^(0|[1-9][0-9]*)(\.[0-9]+)?$/.test(o.giftCost)) {
    throw new InvalidGiftBasisError(`Gift cost ${o.giftCost} is not a decimal`);
  }
}
for (const o of action.input.overrides) {
  const next = { wallet: o.wallet.toLowerCase(), eventId: o.eventId, sequenceIndex: o.sequenceIndex, category: o.category, giftCost: o.giftCost ?? null, giftAcquiredAt: o.giftAcquiredAt ?? null };
  const index = overrides.findIndex((held) => keyOf(held) === keyOf(next));
  if (index === -1) overrides.push(next);
  else overrides[index] = next;
}

operations.schema:
input ClearEventCategoriesInput {
  events: [EventKeyInput!]!
}

input EventKeyInput {
  wallet: String!
  eventId: String!
  sequenceIndex: Int!
}

operations.reducer:
const keyOf = (o: { wallet: string; eventId: string; sequenceIndex: number }) => `${o.wallet.toLowerCase()}|${o.eventId}|${o.sequenceIndex}`;
const gone = new Set(action.input.events.map(keyOf));
state.categoryOverrides = (state.categoryOverrides ?? []).filter((o) => !gone.has(keyOf(o)));
